  r'''[{"module_id": "course_1_module_2", "question_id": "course_1_module_2_q01", "question_number": 1, "stem": "How should the MAGIC study's ROC-derived 7.5-day medication and 21.3-hour solid-fasting cutoffs be used?", "choice_a": "As observational associations, not validated minimum intervals that guarantee an empty stomach", "choice_b": "As mandatory fasting and withholding requirements for every GLP-1 user", "choice_c": "As proof that aspiration cannot occur beyond those intervals", "choice_d": "As replacements for patient-specific assessment", "correct_choice": "a", "rationale": "MAGIC associated these cutoffs with high residual gastric contents. It did not test a randomized intervention or establish aspiration-prevention thresholds.", "source_ids": [5], "source_urls": ["https://pubmed.ncbi.nlm.nih.gov/41032460/"], "learning_objective_ids": [2, 5], "hint": {"type": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}}, {"module_id": "course_1_module_2", "question_id": "course_1_module_2_q02", "question_number": 2, "stem": "Which GLP-1 receptor agonist effect is most directly relevant to retained gastric contents?", "choice_a": "Suppression of airway reflexes through direct neuromuscular blockade", "choice_b": "Guaranteed acceleration of solid-food emptying", "choice_c": "Delayed gastric emptying", "choice_d": "Direct dissolution of particulate gastric contents", "correct_choice": "c", "rationale": "Delayed gastric emptying can leave residual contents despite conventional fasting. This must be separated from an actual aspiration event.", "source_ids": [1], "source_urls": ["https://pmc.ncbi.nlm.nih.gov/articles/PMC12597468/"], "learning_objective_ids": [1], "hint": {"type": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}}, {"module_id": "course_1_module_2", "question_id": "course_1_module_2_q03", "question_number": 3, "stem": "Tirzepatide acts at which receptor combination?", "choice_a": "GIP and GLP-1 receptors", "choice_b": "GLP-1 and opioid mu receptors", "choice_c": "Amylin and nicotinic receptors", "choice_d": "GIP and serotonin 5-HT3 receptors", "correct_choice": "a", "rationale": "Tirzepatide is a dual glucose-dependent insulinotropic polypeptide and GLP-1 receptor agonist.", "source_ids": [1], "source_urls": ["https://pmc.ncbi.nlm.nih.gov/articles/PMC12597468/"], "learning_objective_ids": [1], "hint": {"type": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}}, {"module_id": "course_1_module_2", "question_id": "course_1_module_2_q04", "question_number": 4, "stem": "What is the most accurate interpretation of Elkin et al.'s pooled aspiration result, OR 1.04 (95% CI 0.87\u20131.25)?", "choice_a": "Aspiration was proven impossible in GLP-1 users", "choice_b": "No statistically significant association was demonstrated, with low-certainty evidence", "choice_c": "GLP-1 therapy caused a fourfold increase in aspiration", "choice_d": "All included studies were randomized trials establishing equivalence", "correct_choice": "b", "rationale": "The confidence interval includes 1, and the evidence was observational and low certainty. This does not establish zero risk or equivalence.", "source_ids": [4], "source_urls": ["https://pubmed.ncbi.nlm.nih.gov/40230298/"], "learning_objective_ids": [2, 5], "hint": {"type": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}}, {"module_id": "course_1_module_2", "question_id": "course_1_module_2_q05", "question_number": 5, "stem": "A qualified gastric ultrasound examination estimates clear gastric fluid at 2 mL/kg. What is the best interpretation?", "choice_a": "It proves that 2 mL/kg will be aspirated during induction", "choice_b": "It is automatically normal because the fluid is clear", "choice_c": "It eliminates the need to consider procedure urgency", "choice_d": "It exceeds the commonly used greater-than