  r'''[{"module_id": "course_1_module_4", "question_id": "nmba_01", "question_number": 1, "stem": "Which agent is a nondepolarizing aminosteroid?", "choice_a": "Vecuronium", "choice_b": "Succinylcholine", "choice_c": "Cisatracurium", "choice_d": "Atracurium", "correct_choice": "a", "rationale": "Vecuronium belongs to the aminosteroid class. Cisatracurium and atracurium are benzylisoquinoliniums; succinylcholine is depolarizing.", "source_ids": [3], "source_urls": ["https://pmc.ncbi.nlm.nih.gov/articles/PMC10941205/"], "learning_objective_ids": [1], "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["c", "d"], "remaining_choices": ["a", "b"]}}, {"module_id": "course_1_module_4", "question_id": "nmba_02", "question_number": 2, "stem": "A patient with spinal-cord injury and prolonged immobility requires intubation. Which NMBA carries a particularly important hyperkalemic-arrest risk?", "choice_a": "Rocuronium", "choice_b": "Succinylcholine", "choice_c": "Cisatracurium", "choice_d": "Vecuronium", "correct_choice": "b", "rationale": "Denervation and immobility can increase extrajunctional receptors. Succinylcholine can produce excessive potassium release; its usual rapid onset does not negate this risk.", "source_ids": [4], "source_urls": ["https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=488e1689-84d4-4f96-ac85-fa0cbc661cb6"], "learning_objective_ids": [1, 5], "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["c", "d"], "remaining_choices": ["a", "b"]}}, {"module_id": "course_1_module_4", "question_id": "nmba_03", "question_number": 3, "stem": "Which agent is particularly useful when predominantly organ-independent Hofmann elimination is desired?", "choice_a": "Rocuronium", "choice_b": "Vecuronium", "choice_c": "Cisatracurium", "choice_d": "Pancuronium", "correct_choice": "c", "rationale": "Cisatracurium undergoes predominantly temperature- and pH-dependent Hofmann elimination. Metabolite exposure and monitoring still matte