  r'''{"course_1_module_5": [{"module_id": "course_1_module_5", "question_id": "course_1_module_5_q01", "question_number": 1, "stem": "Which of the following BEST describes the mechanism of action of tranexamic acid?", "choice_a": "Lysine analogue that competitively inhibits plasminogen activation", "choice_b": "Direct thrombin inhibitor that reduces fibrin formation", "choice_c": "Vitamin K antagonist that blocks factor II, VII, IX, X synthesis", "choice_d": "Platelet ADP receptor antagonist", "correct_choice": "a", "rationale": "TXA is a synthetic lysine analogue that binds plasminogen's lysine-binding sites, preventing conversion to plasmin and preserving formed clot. It does not affect thrombin, vitamin K\u2013dependent factors, or platelets directly (Bouras et al., 2024).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [1], "source_ids": [], "source_urls": ["https://doi.org/10.3389/fmed.2024.1416998", "https://doi.org/10.1093/bjs/znaf079", "https://doi.org/10.1056/NEJMoa2207419", "https://doi.org/10.1056/NEJMoa2028788", "https://doi.org/10.1161/CIR.0000000000001285", "https://doi.org/10.1186/s13741-024-00418-3", "https://doi.org/10.1186/s13018-025-05942-6"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_5", "question_id": "course_1_module_5_q02", "question_number": 2, "stem": "Approximately what percentage of tranexamic acid is excreted unchanged in the urine?", "choice_a": "10%", "choice_b": "95%", "choice_c": "30%", "choice_d": "60%", "correct_choice": "b", "rationale": "Approximately 95% of TXA is excreted unchanged in urine, which is why renal impairment is the most important pharmacokinetic variable driving both efficacy and adverse-effect risk (Eugia US LLC, 2025).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [1], "source_ids": [], "source_urls": ["https://doi.org/10.3389/fmed.2024.1416998", "https://doi.org/10.1093/bjs/znaf079", "https://doi.org/10.1056/NEJMoa2207419", "https://doi.org/10.1056/NEJMoa2028788", "https://doi.org/10.1161/CIR.0000000000001285", "https://doi.org/10.1186/s13741-024-00418-3", "https://doi.org/10.1186/s13018-025-05942-6"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_5", "question_id": "course_1_module_5_q03", "question_number": 3, "stem": "When should TXA be administered to an eligible adult trauma patient with hemorrhagic shock?", "choice_a": "At any time during the first 24 hours", "choice_b": "Only after hemorrhage has stopped", "choice_c": "As soon as possible, no later than 3 hours after injury", "choice_d": "Wait until 2 hours after injury", "correct_choice": "c", "rationale": "Benefit is time-sensitive. TXA must not delay immediate lifesaving measures.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [2], "source_ids": [4], "source_urls": ["https://www.tandfonline.com/doi/full/10.1080/10903127.2025.2497056"], "source_provenance": "verified_targeted_update"}, {"module_id": "course_1_module_5", "question_id": "course_1_module_5_q04", "question_number": 4, "stem": "A bleeding trauma patient arrives 4 hours after injury without a prior TXA dose. Which statement is most accurate?", "choice_a": "All late presenters should receive TXA", "choice_b": "Delay longer to improve antifibrinolytic efficacy", "choice_c": "Severe TBI always overrides the timing limit", "choice_d": "Routine initiation beyond 3 hours is not supported and may be harmful", "correct_choice": "d", "rationale": "Do not create a routine late-treatment exception from secondary subgroup analysis.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [2], "source_ids": [4], "source_urls": ["https://www.tandfonline.com/doi/full/10.1080/10903127.2025.2497056"], "source_provenance": "verified_targeted_update"}, {"module_id": "course_1_module_5", "question_id": "course_1_module_5_q05", "question_number": 5, "stem": "Which of the following is the standard TXA dose for treatment of postpartum hemorrhage?", "choice_a": "1 g IV over 10 minutes", "choice_b": "10 mg/kg IM", "choice_c": "2 g IV bolus", "choice_d": "500 mg IV over 2 minutes", "correct_choice": "a", "rationale": "WHO recommends 1 g IV over 10 minutes as soon as possible within 3 hours of birth. Repeat 1 g if bleeding continues after 30 minutes or restarts within 24 hours.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [2], "source_ids": [2], "source_urls": ["https://iris.who.int/bitstream/handle/10665/259379/WHO-RHR-17.21-eng.pdf"], "source_provenance": "verified_targeted_update"}, {"module_id": "course_1_module_5", "question_id": "course_1_module_5_q06", "question_number": 6, "stem": "Regarding prophylactic TXA during cesarean delivery, which statement best reflects the 2023 Pacheco NEJM trial findings?", "choice_a": "Prophylactic TXA eliminated the need for uterotonics", "choice_b": "Prophylactic TXA did not significantly reduce a composite of maternal death or blood transfusion", "choice_c": "Prophylactic TXA increased thromboembolic events", "choice_d": "Prophylactic TXA significantly reduced maternal death or transfusion", "correct_choice": "b", "rationale": "The 2023 Pacheco NEJM trial in >11,000 cesarean deliveries found no significant reduction in the composite outcome of maternal death or transfusion with prophylactic TXA. Treatment TXA for diagnosed hemorrhage remains supported (Pacheco et al., 2023).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [2], "source_ids": [], "source_urls": ["https://doi.org/10.3389/fmed.2024.1416998", "https://doi.org/10.1093/bjs/znaf079", "https://doi.org/10.1056/NEJMoa2207419", "https://doi.org/10.1056/NEJMoa2028788", "https://doi.org/10.1161/CIR.0000000000001285", "https://doi.org/10.1186/s13741-024-00418-3", "https://doi.org/10.1186/s13018-025-05942-6"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_5", "question_id": "course_1_module_5_q07", "question_number": 7, "stem": "Which adverse effect of TXA is MOST dose-dependent and is amplified by renal impairment and cardiac surgery?", "choice_a": "Hepatotoxicity", "choice_b": "Anaphylaxis", "choice_c": "Seizures", "choice_d": "Hypertension", "correct_choice": "c", "rationale": "Seizure risk increases with high exposure, renal accumulation, and cardiac-surgery regimens. Follow renal dose adjustment and avoid neuraxial administration.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [1], "source_ids": [1], "source_urls": ["https://dailymed.nlm.nih.gov/dailymed/fda/fdaDrugXsl.cfm?setid=246a3c6c-a7fb-45c7-9509-49a48a5bdcc6"], "source_provenance": "verified_targeted_update"}, {"module_id": "course_1_module_5", "question_id": "course_1_module_5_q08", "question_number": 8, "stem": "A CRNA is preparing for a cardiac case in a 71-year-old with an eGFR of 32 mL/min/1.73 m\u00b2. Which TXA strategy is most appropriate?", "choice_a": "Standard high-dose regimen; renal function is not a factor", "choice_b": "Avoid TXA entirely regardless of bleeding risk", "choice_c": "Substitute epsilon-aminocaproic acid at equivalent doses", "choice_d": "Lower cumulative dose with careful postoperative neurologic monitoring", "correct_choice": "d", "rationale": "In renal impairment, TXA accumulates and seizure risk rises. The safest plan preserves efficacy while limiting accumulation \u2014 lower cumulative doses, careful monitoring, and heightened postoperative neurologic vigilance (La Via et al., 2025).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [5], "source_ids": [], "source_urls": ["https://doi.org/10.3389/fmed.2024.1416998", "https://doi.org/10.1093/bjs/znaf079", "https://doi.org/10.1056/NEJMoa2207419", "https://doi.org/10.1056/NEJMoa2028788", "https://doi.org/10.1161/CIR.0000000000001285", "https://doi.org/10.1186/s13741-024-00418-3", "https://doi.org/10.1186/s13018-025-05942-6"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_5", "question_id": "course_1_module_5_q09", "question_number": 9, "stem": "Inadvertent intrathecal or epidural TXA administration is associated with which of the following?", "choice_a": "Refractory seizures, ventricular arrhythmia, and high mortality", "choice_b": "Prolonged sensory block only", "choice_c": "Transient headache with full recovery", "choice_d": "Delayed opioid tolerance", "correct_choice": "a", "rationale": "Wrong-route neuraxial TXA can cause catastrophic seizures, arrhythmias, and death. Immediate resuscitation and specialist consultation are essential.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [3], "source_ids": [1], "source_urls": ["https://dailymed.nlm.nih.gov/dailymed/fda/fdaDrugXsl.cfm?setid=246a3c6c-a7fb-45c7-9509-49a48a5bdcc6"], "source_provenance": "verified_targeted_update"}, {"module_id": "course_1_module_5", "question_id": "course_1_module_5_q10", "question_number": 10, "stem": "Which system-level safeguard helps prevent wrong-route TXA administration?", "choice_a": "Verbal reminders during handoff", "choice_b": "Route separation: TXA stored separately from neuraxial local anesthetics", "choice_c": "Documentation in the anesthesia record", "choice_d": "Postoperative debriefing after every case", "correct_choice": "b", "rationale": "Separate TXA from neuraxial medications and combine separation with clear labeling, route verification, and team checks.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [4], "source_ids": [1], "source_urls": ["https://dailymed.nlm.nih.gov/dailymed/fda/fdaDrugXsl.cfm?setid=246a3c6c-a7fb-45c7-9509-49a48a5bdcc6"], "source_provenance": "verified_targeted_update"}, {"module_id": "course_1_module_5", "question_id": "course_1_module_5_q11", "question_number": 11, "stem": "When elective surgery requires antiplatelet interruption after DES placement for acute coronary syndrome, the usual minimum delay is:", "choice_a": "3 months for every patient", "choice_b": "6 weeks", "choice_c": "12 months", "choice_d": "30 days", "correct_choice": "c", "rationale": "Guidance distinguishes DES for ACS from DES for chronic coronary disease; selected time-sensitive surgery requires separate multidisciplinary assessment.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [3], "source_ids": [3], "source_urls": ["https://www.ccjm.org/content/92/4/213"], "source_provenance": "verified_targeted_update"}, {"module_id": "course_1_module_5", "question_id": "course_1_module_5_q12", "question_number": 12, "stem": "A 2024 meta-analysis (Tian et al.) of TXA in cardiac surgical patients on antiplatelet therapy found:", "choice_a": "Increased mortality", "choice_b": "No effect on any outcome", "choice_c": "Increased bleeding and transfusion with TXA", "choice_d": "Reduced bleeding and transfusion without a significant increase in MI or stroke", "correct_choice": "d", "rationale": "Tian et al. (2024) demonstrated that TXA reduces bleeding and transfusion in cardiac surgical patients maintained on antiplatelet therapy without a significant increase in perioperative MI or stroke (Tian et al., 2024).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [2], "source_ids": [], "source_urls": ["https://doi.org/10.3389/fmed.2024.1416998", "https://doi.org/10.1093/bjs/znaf079", "https://doi.org/10.1056/NEJMoa2207419", "https://doi.org/10.1056/NEJMoa2028788", "https://doi.org/10.1161/CIR.0000000000001285", "https://doi.org/10.1186/s13741-024-00418-3", "https://doi.org/10.1186/s13018-025-05942-6"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_5", "question_id": "course_1_module_5_q13", "question_number": 13, "stem": "Which statement best guides topical versus IV TXA selection in a patient with prior DVT?", "choice_a": "Lower systemic exposure does not establish lower thrombosis risk; individualize the plan", "choice_b": "All prior DVT requires combined IV and topical TXA", "choice_c": "Route selection eliminates the need to assess renal function", "choice_d": "Topical TXA guarantees no thrombosis", "correct_choice": "a", "rationale": "A route with lower exposure should not be presented as proven safer for every thrombotic-risk patient.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [5], "source_ids": [1], "source_urls": ["https://dailymed.nlm.nih.gov/dailymed/fda/fdaDrugXsl.cfm?setid=246a3c6c-a7fb-45c7-9509-49a48a5bdcc6"], "source_provenance": "verified_targeted_update"}, {"module_id": "course_1_module_5", "question_id": "course_1_module_5_q14", "question_number": 14, "stem": "Which of the following is the standard CRASH-2 trauma regimen?", "choice_a": "15 mg/kg IV once, no infusion", "choice_b": "1 g IV over 10 min, then 1 g infusion over 8 h", "choice_c": "500 mg IV over 5 min, then 500 mg over 4 h", "choice_d": "2 g IV bolus only", "correct_choice": "b", "rationale": "The CRASH-2 regimen (1 g IV over 10 min followed by 1 g infusion over 8 hours) is the reference standard for trauma dosing (CRASH-2 trial collaborators, 2010).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [2], "source_ids": [], "source_urls": ["https://doi.org/10.3389/fmed.2024.1416998", "https://doi.org/10.1093/bjs/znaf079", "https://doi.org/10.1056/NEJMoa2207419", "https://doi.org/10.1056/NEJMoa2028788", "https://doi.org/10.1161/CIR.0000000000001285", "https://doi.org/10.1186/s13741-024-00418-3", "https://doi.org/10.1186/s13018-025-05942-6"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_5", "question_id": "course_1_module_5_q15", "question_number": 15, "stem": "Which of the following is a labeled contraindication to TXA injection?", "choice_a": "Prior use of ondansetron", "choice_b": "Age >65", "choice_c": "Active intravascular clotting or documented hypersensitivity to TXA", "choice_d": "History of dental extraction", "correct_choice": "c", "rationale": "Active intravascular clotting and hypersensitivity are contraindications. The cited label also contraindicates subarachnoid hemorrhage and neuraxial administration.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [3], "source_ids": [1], "source_urls": ["https://dailymed.nlm.nih.gov/dailymed/fda/fdaDrugXsl.cfm?setid=246a3c6c-a7fb-45c7-9509-49a48a5bdcc6"], "source_provenance": "verified_targeted_update"}, {"module_id": "course_1_module_5", "question_id": "course_1_module_5_q16", "question_number": 16, "stem": "A CRNA notices a syringe labeled for neuraxial injection contains TXA drawn from an IV vial next to bupivacaine ampules. Which action is most appropriate?", "choice_a": "Give the TXA IV instead", "choice_b": "Proceed cautiously with the neuraxial block", "choice_c": "Delay the report until after surgery", "choice_d": "Discard the syringe, report the near miss, and review the medication-setup workflow", "correct_choice": "d", "rationale": "Discard, disclose, and redesign. The APSF/ISMP framework treats every near miss as evidence that medication-system design must be strengthened. Silent correction perpetuates the underlying hazard (APSF/ISMP, 2025).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [4], "source_ids": [], "source_urls": ["https://doi.org/10.3389/fmed.2024.1416998", "https://doi.org/10.1093/bjs/znaf079", "https://doi.org/10.1056/NEJMoa2207419", "https://doi.org/10.1056/NEJMoa2028788", "https://doi.org/10.1161/CIR.0000000000001285", "https://doi.org/10.1186/s13741-024-00418-3", "https://doi.org/10.1186/s13018-025-05942-6"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_5", "question_id": "course_1_module_5_q17", "question_number": 17, "stem": "Which statement about TXA and thromboembolic risk is best supported by CRASH-2 and WOMAN data?", "choice_a": "TXA at standard doses does not significantly increase thromboembolic events", "choice_b": "Standard TXA doses substantially increase DVT and PE rates", "choice_c": "TXA converts warfarin therapy into a thrombogenic exposure", "choice_d": "TXA is contraindicated in all patients with prior VTE", "correct_choice": "a", "rationale": "CRASH-2 and WOMAN did not show increased thromboembolic events at standard TXA doses. Caution remains warranted in patients with active thromboembolic disease or on combined hormonal contraceptives.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [3], "source_ids": [], "source_urls": ["https://doi.org/10.3389/fmed.2024.1416998", "https://doi.org/10.1093/bjs/znaf079", "https://doi.org/10.1056/NEJMoa2207419", "https://do